/**
 * Curated starter set of ~90 well-known species across the animal kingdom.
 * This is intentionally hand-picked rather than exhaustive — per the project
 * brief, the app starts with the most recognizable species in each major
 * group and grows from there (via GBIF sync, and future contributor PRs).
 *
 * The original ~53-species set was heavily mammal-biased (27 mammals vs.
 * single digits for most other groups) and Europe was the thinnest
 * continent (12 species) — see the "More species..." blocks below, added
 * specifically to broaden both continent and animal-group coverage rather
 * than adding more of what was already well represented.
 *
 * Figures (size, lifespan, status) are approximate, general-knowledge
 * figures meant for an engaging demo, not a scientific reference. Swap in
 * IUCN-sourced values whenever accuracy matters more than coverage — or hit
 * "Refresh data" in the app, which now pulls a real status from the IUCN checklist on GBIF/
 * IUCN automatically (see src/main/services/conservationStatus.ts).
 */

export type ConservationStatus =
  | 'EXTINCT'
  | 'EXTINCT_IN_WILD'
  | 'CRITICALLY_ENDANGERED'
  | 'ENDANGERED'
  | 'VULNERABLE'
  | 'NEAR_THREATENED'
  | 'LEAST_CONCERN'
  | 'DATA_DEFICIENT'

export interface SeedSpecies {
  common_name: string
  scientific_name: string
  animal_group: string
  kingdom: string
  phylum: string
  class_name: string
  order_name: string
  family: string
  genus: string
  description: string
  conservation_status: ConservationStatus
  habitat: string
  diet: string
  size_cm: number
  lifespan_years: number
  behavior: string
  migratory: boolean
  continents: string[]
}

